/**
 * 内置在 Winlator 里的数位板桥（无 root、无命令、无常驻进程）。
 *
 * smali 侧只有两处调用：
 *   - {@link #configure(int, int)}        容器分辨率（updateXform 里）
 *   - {@link #handle(View, MotionEvent)}  TouchpadView 的触摸/悬停入口
 *
 * handle() 做三件事，全部在 Java 里完成（上一版把分支写在 smali 里导致
 * VerifyError，一进容器就 FATAL）：
 *   1. 采样压感 → UDP:47800 → wintab32.dll → SAI
 *   2. 识别数位板（设备名含 "Pen"；实测 getToolType()/getSource() 都不可靠）
 *   3. 用压力合成 X 指针左键按下/抬起 —— 根治"笔能画、点不了 UI"：
 *      这支 BLE 笔只送 HOVER_MOVE/ACTION_MOVE + 压力，从不送 ACTION_BUTTON_PRESS，
 *      所以 Winlator 原生逻辑永远不会按下左键。
 *
 * 这里不直接引用 com.winlator.* 的类，全部走反射：
 *  - 编译只需要 android.jar，不用维护 stub
 *  - 任何反射失败都只是"笔点击失效"，不会拖垮 App
 *
 * 报文： "seq pressure x y w h"（x,y 原点左下、y 向上；w,h 为容器分辨率）
 */
public final class PenBridge {

    private static final String TAG = "SaiPen";
    private static final int PORT = 47800;
    private static final int PMAX = 4095;
    /* 发送给 wintab32.dll 的坐标用 8 倍定点：协议里 x/w、y/h 只取比例，
     * 所以 8 倍不会改变位置，只把 1px 量化误差降到 1/8px。DLL 自己的
     * wtc_screen_to_sample() 也用了同样的 8 倍约定。 */
    private static final int POS_SCALE = 8;

    /**
     * 落笔判据分两层：
     *  - 动作层：ACTION_DOWN/ACTION_MOVE 只会在笔尖真正接触时出现（悬停是 HOVER_*）
     *  - 压力层：兜底，笔若只靠压力表达接触（某些驱动），压力够大也算按下
     * 只用压力会被悬停抖动（0.09 上下）骗出误点击，所以动作优先。
     */
    /* 任意压力即落笔：0.0f 表示"只要有压力就触发"。
     * 原来 PRESS_STRONG = 0.35f，接触压力 0.03 / 移动中 0.005 的笔永远够不到，
     * 只能靠 ACTION_DOWN 兜底；悬停派发为主的笔会完全点不动。 */
    /* 发送上限：约 166 Hz。手写笔硬件常报 200~250 Hz，而 SAI 在 box64 下
     * 每个样本都要重绘一小段；把中间点丢掉（只发最新位置）能显著降低负载，
     * 线条形状由 SAI 自己插值，肉眼几乎无差别。 */
    private static final long MIN_SEND_MS = 6;
    private static long lastSendMs;

    private static final float PRESS_MIN = 0.001f;
    private static final float PRESS_STRONG = 0.0f;
    /** 超过这么久没收到笔事件就认为笔已离开（BLE 可能不给 HOVER_EXIT）。 */
    private static final long LOST_MS = 700;

    private static final Object LOCK = new Object();

    private static DatagramSocket socket;
    private static InetAddress loopback;
    private static boolean starting;
    private static boolean disabled;

    private static int screenW = 1280;
    private static int screenH = 720;

    private static int pendingX, pendingY, pendingP;
    private static boolean hasPending;
    /* 长线积压时的空间抽稀：只在上一次真正入队的点足够远时才再入队。 */
    private static int lastQueuedX = -100000, lastQueuedY = -100000;

    private static int seq = 1;
    private static int sentCount;
    private static int lastAction = -1;
    private static float lastPressure = -1f;

    /* ---- 反射句柄（一次性解析并缓存） ---- */
    private static boolean reflectTried;
    private static Field fXServer;
    private static Field fXform;
    private static Method mTransformPoint;
    private static Method mInjectPointerMove;
    private static Method mInjectPress;
    private static Method mInjectRelease;
    private static Object BUTTON_LEFT;
    private static Method mInjectKeyPress;
    private static Method mInjectKeyRelease;
    private static Object KEY_PRIOR;
    private static Object KEY_NEXT;
    /* 触控屏手势要注入的按键（XKeycode 常量，全部反射取）。 */
    private static Object KEY_CTRL_L;
    private static Object KEY_SHIFT_L;
    private static Object KEY_SPACE;
    private static Object KEY_Z;
    private static Object KEY_Y;
    private static Object KEY_0;
    private static boolean wheelLogged;

    /* TouchpadView 原生多指状态：由 PenBridge 在识别出手势时清空，
     * 防止原生两指滚动/右键逻辑和我们的手势同时生效。 */
    private static Field fNativeFingers;
    private static Field fNativeNumFingers;
    private static Field fNativeScrolling;

    /* 虚拟按键（InputControlsView 上的按钮）：按下鼠标类按钮前，先把系统光标
     * 移到手指位置。否则点击会落在旧光标处，表现为“虚拟按钮点不动”。 */
    private static Field fControlBindings;
    private static Field fControlInputControlsView;
    private static Method mBindingGetPointerButton;
    private static Method mInputControlsGetTouchpadView;

    /** 我们合成出来的左键是否处于按下状态。 */
    private static boolean penDown;
    /* 手指按下期间（按下由 Winlator 原生补丁处理，我们只负责兜底松手） */
    private static java.lang.reflect.Field fPointer;
    private static java.lang.reflect.Method mIsPressed;
    private static boolean fingerActive;
    /* 手指落笔延迟到移动超过阈值才开始：否则两指手势的第一根手指会先画一个点，
     * 两指轻点撤销时 Ctrl+Z 撤销的是这个点，而不是用户想撤销的那一笔。 */
    private static boolean fingerDrawing;
    private static boolean fingerSuppressed;
    private static float fingerStartViewX, fingerStartViewY;
    private static int fingerLastX, fingerLastY;
    private static float fingerLastPressure;
    private static final float FINGER_DRAW_PX = 8f;
    /* 落笔/抬笔样本单独排队：绝不合并，保证 SAI 一定收到 UP 和下一笔的 DOWN。
     * 抬笔时还会追加两个位置不同的零压样本，见 emit()。 */
    private static final java.util.ArrayDeque<int[]> CRIT = new java.util.ArrayDeque<>();
    private static long lastPenEventMs;
    /** 最近一次笔尖接触（给 CoreTuner 判断是否在画）。 */
    private static volatile long lastPenTouchMs;
    /** 只在第一次见到笔时打一条诊断日志（设备源类型）。 */
    private static boolean loggedPen;

    private PenBridge() {}

    /** updateXform 调用，告知当前容器的显示分辨率（Windows 像素）。 */
    /* ---- 自愈：把 wintab32.dll 补回容器 ----
     * Wine 在容器首次启动时会把自带的 builtin wintab32.dll 拷进 system32，
     * 容器模板里预置的那份会被覆盖。这里在容器界面起来时检查文件大小，
     * 不是我们的 185,607 字节就重新写一份——早于 SAI 启动，所以来得及。
     * DLL 以 base64 嵌在 dex 里（dex 单个字符串上限 65,535，故分块）。
     */
    private static final String B64_64_0 = "";
    private static final String B64_64_1 = "";
    private static final String B64_64_2 = "";
    private static final String B64_32_0 = "";
    private static final String B64_32_1 = "";
    private static final String B64_32_2 = "";

    private static final String[] B64_64 = {
B64_64_0,
B64_64_1,
B64_64_2
    };
    private static final String[] B64_32 = {
B64_32_0,
B64_32_1,
B64_32_2
    };
    private static final int OUR_DLL_SIZE_64 = 92160;
    private static final int OUR_DLL_SIZE_32 = 85504;
    private static final String CONTAINER_DLL_64 =
            "/data/data/com.winlator/files/rootfs/home/xuser/.wine/drive_c/windows/system32/wintab32.dll";
    private static final String CONTAINER_DLL_32 =
            "/data/data/com.winlator/files/rootfs/home/xuser/.wine/drive_c/windows/syswow64/wintab32.dll";
    private static final String CONTAINER_PMAX =
            "/data/data/com.winlator/files/rootfs/home/xuser/.wine/drive_c/wt_pmax.txt";
    private static final String CONTAINER_BRIDGE_VER =
            "/data/data/com.winlator/files/rootfs/home/xuser/.wine/drive_c/wt_bridge_ver.txt";
    private static final String BRIDGE_VERSION = "wintab-2026-11-21-7";
    private static boolean bridgeFilesChecked;

    private static void ensureBridgeFiles() {
        if (bridgeFilesChecked) return;
        bridgeFilesChecked = true;
        try {
            boolean force = !BRIDGE_VERSION.equals(readText(CONTAINER_BRIDGE_VER));
            writeEmbeddedDll(CONTAINER_DLL_64, B64_64, OUR_DLL_SIZE_64, force);
            writeEmbeddedDll(CONTAINER_DLL_32, B64_32, OUR_DLL_SIZE_32, force);
            writeText(CONTAINER_BRIDGE_VER, BRIDGE_VERSION);
            java.io.File pmax = new java.io.File(CONTAINER_PMAX);
            if (!pmax.exists()) {
                java.io.FileOutputStream fo3 = new java.io.FileOutputStream(pmax);
                try { fo3.write(new byte[]{'4', '0', '9', '5'}); } finally { fo3.close(); }
            }
        } catch (Throwable t) {
            try { Log.w(TAG, "ensureBridgeFiles: " + t); } catch (Throwable ignored) { }
        }
    }

    private static String readText(String path) {
        try {
            java.io.File f = new java.io.File(path);
            if (!f.exists()) return "";
            byte[] b = new byte[(int) f.length()];
            java.io.FileInputStream in = new java.io.FileInputStream(f);
            try { int n = in.read(b); return n > 0 ? new String(b, 0, n, "UTF-8").trim() : ""; }
            finally { in.close(); }
        } catch (Throwable t) { return ""; }
    }

    private static void writeText(String path, String text) {
        try {
            java.io.File f = new java.io.File(path);
            java.io.FileOutputStream out = new java.io.FileOutputStream(f);
            try { out.write(text.getBytes("UTF-8")); } finally { out.close(); }
        } catch (Throwable ignored) { }
    }

    private static void writeEmbeddedDll(String path, String[] parts, int size, boolean force) {
        try {
            java.io.File dllFile = new java.io.File(path);
            if (!force && dllFile.length() == size) return;
            StringBuilder sb = new StringBuilder(size * 4 / 3 + 8);
            for (String part : parts) sb.append(part);
            byte[] data = android.util.Base64.decode(sb.toString(), android.util.Base64.DEFAULT);
            if (data.length != size) return;
            java.io.File parent = dllFile.getParentFile();
            if (parent != null && !parent.exists()) parent.mkdirs();
            java.io.File tmp = new java.io.File(parent, "wintab32.dll.new");
            java.io.FileOutputStream fos = new java.io.FileOutputStream(tmp);
            try { fos.write(data); } finally { fos.close(); }
            tmp.setReadable(true, false);
            if (!tmp.renameTo(dllFile)) {
                java.io.FileOutputStream fo2 = new java.io.FileOutputStream(dllFile);
                try { fo2.write(data); } finally { fo2.close(); }
                tmp.delete();
            }
            note("bridge dll restored " + path + " " + data.length);
        } catch (Throwable t) {
            try { Log.w(TAG, "writeEmbeddedDll " + path + ": " + t); } catch (Throwable ignored) { }
        }
    }

    /**
     * 物理滚轮 -> SAI 缩放。
     *
     * SAI 默认把 PageUp/PageDown 绑定为「以光标为中心放大/缩小」。Winlator 把滚轮
     * 原样转成 X11 button 4/5 时，SAI 收到的是滚动而不是缩放（实测在 [PivInk]SAI 上
     * 画布会上下移动）。这里在 Android 侧直接把滚轮翻译成 PageUp/PageDown，
     * 不再依赖 Wine 的滚轮消息路径。
     */
    public static void zoomIn(View pad) { wheelZoom(pad, true); }

    public static void zoomOut(View pad) { wheelZoom(pad, false); }

    private static void wheelZoom(View pad, boolean in) {
        if (pad == null) return;
        resolveReflection();
        try {
            if (fXServer == null || mInjectKeyPress == null || mInjectKeyRelease == null) return;
            Object xs = fXServer.get(pad);
            if (xs == null) return;
            Object key = in ? KEY_PRIOR : KEY_NEXT;
            mInjectKeyPress.invoke(xs, key);
            mInjectKeyRelease.invoke(xs, key);
            if (!wheelLogged) {
                wheelLogged = true;
                note("wheel -> " + (in ? "PageUp" : "PageDown") + " (SAI zoom)");
                flog("wheel zoom " + (in ? "in" : "out"));
            }
        } catch (Throwable t) {
            try { Log.w(TAG, "wheelZoom: " + t); } catch (Throwable ignored) { }
        }
    }

    public static void configure(int width, int height) {
        ensureBridgeFiles();
        CoreTuner.start();
        try {
            if (width > 0 && height > 0) {
                screenW = width;
                screenH = height;
            }
        } catch (Throwable ignored) {
        }
    }

    /** 最近 1.2s 内是否有笔尖接触，CoreTuner 用。 */
    static boolean isDrawingRecently() {
        return SystemClock.uptimeMillis() - lastPenTouchMs < 1200;
    }

    /** 诊断日志。 */
    public static void note(String s) {
        try {
            Log.d(TAG, s);
        } catch (Throwable ignored) {
        }
    }

    /**
     * 外接鼠标/笔入口（onExternalMouseEvent）。单指手势不在这里发生。
     */
    public static void handle(View pad, MotionEvent ev) {
        if (pad == null || ev == null) return;
        ensureBridgeFiles();
        final boolean pen = isPen(ev);
        if (pen) TouchGestures.cancel(pad);
        handleEvent(pad, ev, pen, false);
    }

    /**
     * 触屏入口（onTouchEvent）。返回 true 表示该事件已被手势消费：
     * smali 侧会直接 return true，原生 TouchpadView 的两指滚动/右键逻辑不再执行。
     *
     * 单指事件返回 false，保持原有单指作画/点击行为不变。
     */
    public static boolean handleTouch(View pad, MotionEvent ev) {
        if (pad == null || ev == null) return false;
        ensureBridgeFiles();
        final boolean pen = isPen(ev);
        if (pen) {
            TouchGestures.cancel(pad);
            handleEvent(pad, ev, true, false);
            return false;
        }
        final boolean consumed = TouchGestures.onTouch(pad, ev);
        handleEvent(pad, ev, false, consumed);
        return consumed;
    }

    private static void handleEvent(View pad, MotionEvent ev, boolean pen, boolean consumed) {
        try {
            final int action = ev.getActionMasked();
            final float pressure = ev.getPressure();

            // 诊断：设备没有 logcat 时写到 app 自己的目录，adb root 可直接读。
            // 悬停事件太多，只记非悬停（DOWN/MOVE/UP 等）。
            if (action != MotionEvent.ACTION_HOVER_MOVE) {
                flog("ev act=" + action
                        + " src=0x" + Integer.toHexString(ev.getSource())
                        + " tool=" + ev.getToolType(0)
                        + " pr=" + pressure
                        + " synth=" + needsSyntheticClick(ev)
                        + " t=" + SystemClock.uptimeMillis());
            }

            int[] xy = toContainer(pad, ev);
            int[] xys = toContainerScaled(pad, ev);
            if (xy == null || xys == null) return;
            final int x = xy[0], y = xy[1];
            final int sx = xys[0], sy = xys[1];

            // 诊断：只对 DOWN 记录一次原始/变换后坐标，确认为什么画笔会贴边
            if (action == MotionEvent.ACTION_DOWN) {
                flog("MAP view=" + (int) ev.getX() + "," + (int) ev.getY()
                        + " raw=" + (int) ev.getRawX() + "," + (int) ev.getRawY()
                        + " viewSize=" + pad.getWidth() + "x" + pad.getHeight()
                        + " screen=" + screenW + "x" + screenH
                        + " -> " + x + "," + y);
            }

            if (!pen) {
                handleFingerTouch(pad, ev, consumed, sx, sy);
                return;
            }

            // ---------------- 以下全部是笔的原有逻辑 ----------------
            if (action == MotionEvent.ACTION_DOWN || action == MotionEvent.ACTION_MOVE
                    || action == MotionEvent.ACTION_POINTER_DOWN || pressure > 0f) {
                lastPenTouchMs = SystemClock.uptimeMillis();
            }
            // 1) 压感采样（笔自己会在抬笔后继续送悬停事件，不需要我们补）
            // Android 把一帧内的笔样本合并进一个 MotionEvent 的 history；
            // 这些历史样本全部送给 DLL（压力曲线不丢），但光标只在本事件末尾
            // 移到最新点一次。每次 injectPointerMove 都要走 X server -> Wine ->
            // SAI，按样本移动是 Box64 下最大的输入开销。
            final int hist = ev.getHistorySize();
            for (int h = 0; h < hist; h++) {
                int[] hxy = toContainerAt(pad, ev.getHistoricalX(h), ev.getHistoricalY(h));
                int[] hxys = toContainerScaledAt(pad, ev.getHistoricalX(h), ev.getHistoricalY(h));
                if (hxy != null && hxys != null) {
                    emit(hxys[0], hxys[1], ev.getHistoricalPressure(h),
                         MotionEvent.ACTION_MOVE, false, true);
                }
            }

            // 光标每个事件只移一次，移到最新样本。
            moveCursorTo(pad, x, y);

            final boolean queueAll = action == MotionEvent.ACTION_MOVE
                    || action == MotionEvent.ACTION_HOVER_MOVE
                    || action == MotionEvent.ACTION_HOVER_ENTER;
            emit(sx, sy, pressure, action, false, queueAll);

            // 2) 只有"鼠标型笔"才合成左键（正规 STYLUS 交给 Winlator 原生处理）
            if (!loggedPen) {
                loggedPen = true;
                note("pen src=0x" + Integer.toHexString(ev.getSource())
                        + " tool=" + ev.getToolType(0)
                        + " synth=" + needsSyntheticClick(ev));
            }
            if (needsSyntheticClick(ev)) {
                syncLeftButton(pad, x, y, pressure, action);
            } else {
                // 正规 STYLUS（S Pen）：原生 tap 已经会点，我们只在拖动/长按时补按下
                syncDragOnly(pad, x, y, pressure, ev, action);
            }
        } catch (Throwable ignored) {
        }
    }

    /**
     * 手指路径。
     *
     * 和旧版的区别只有一点：单指 DOWN 不再立刻发压感样本，而是等到移动超过
     * FINGER_DRAW_PX 才发第一包。这样两指/三指手势的第一根手指不会先落一个点，
     * 也避免了"两指轻点撤销"只撤销了这个点。单指拖动画线仍然从越过阈值的位置开始。
     *
     * consumed=true 或 pointerCount>=2 时，把已经开始的单指笔画收笔并停止采样，
     * 后续交给 {@link TouchGestures} 注入快捷键/鼠标操作。
     */
    private static void handleFingerTouch(View pad, MotionEvent ev, boolean consumed, int x, int y) {
        final int action = ev.getActionMasked();
        final int count = ev.getPointerCount();
        final float pressure = ev.getPressure();
        final long now = SystemClock.uptimeMillis();

        if (action == MotionEvent.ACTION_DOWN) {
            // 新的一次触摸：允许单指作画，并清掉上一次手势的抑制状态。
            fingerSuppressed = false;
            fingerDrawing = false;
            fingerActive = false;
            fingerStartViewX = ev.getX();
            fingerStartViewY = ev.getY();
            fingerLastX = x;
            fingerLastY = y;
            fingerLastPressure = pressure;
            lastPenEventMs = now;
            return;
        }

        if (fingerSuppressed) {
            if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                fingerSuppressed = false;
            }
            fingerActive = false;
            return;
        }

        if (consumed || count >= 2) {
            if (fingerDrawing) endFingerStroke(pad, "gesture");
            fingerDrawing = false;
            fingerActive = false;
            fingerSuppressed = true;
            lastPenEventMs = now;
            return;
        }

        switch (action) {
            case MotionEvent.ACTION_MOVE:
                if (!fingerDrawing) {
                    final float dx = ev.getX() - fingerStartViewX;
                    final float dy = ev.getY() - fingerStartViewY;
                    if ((dx * dx + dy * dy) < FINGER_DRAW_PX * FINGER_DRAW_PX) {
                        fingerLastX = x;
                        fingerLastY = y;
                        fingerLastPressure = pressure;
                        return;
                    }
                    fingerDrawing = true;
                    fingerActive = true;
                    lastPenEventMs = now;
                    armReleaseWatchdog(pad);
                    flog("FINGER_DRAW start " + x + "," + y);
                    emit(x, y, pressure, MotionEvent.ACTION_DOWN, true);
                } else {
                    lastPenEventMs = now;
                    emit(x, y, pressure, MotionEvent.ACTION_MOVE, true);
                }
                fingerLastX = x;
                fingerLastY = y;
                fingerLastPressure = pressure;
                break;

            case MotionEvent.ACTION_UP:
            case MotionEvent.ACTION_CANCEL:
                if (fingerDrawing) endFingerStroke(pad, "finger-up act=" + action);
                fingerActive = false;
                fingerSuppressed = false;
                break;

            default:
                break;
        }
    }

    /** 结束当前手指笔画（幂等）。 */
    private static void endFingerStroke(View pad, String why) {
        if (!fingerDrawing) return;
        fingerDrawing = false;
        fingerActive = false;
        emit(fingerLastX, fingerLastY, fingerLastPressure, MotionEvent.ACTION_UP, true);
        forceRelease(pad, why);
        flog("FINGER_DRAW end " + why);
    }

    /** 诊断日志写文件（这台设备 logd 被关，logcat 读不到任何东西）。 */
    private static java.io.FileWriter logWriter;
    private static int logCount;

    private static void flog(String s) {
        if (logCount > 400) return;
        try {
            if (logWriter == null) {
                logWriter = new java.io.FileWriter("/data/data/com.winlator/files/pb.log", false);
            }
            logWriter.write(s + "\n");
            logWriter.flush();
            logCount++;
        } catch (Throwable ignored) {
        }
    }

    private static void moveCursorTo(View pad, int x, int y) {
        resolveReflection();
        try {
            if (fXServer == null || mInjectPointerMove == null) return;
            Object xs = fXServer.get(pad);
            if (xs != null) mInjectPointerMove.invoke(xs, x, y);
        } catch (Throwable ignored) {
        }
    }

    private static boolean isPen(MotionEvent ev) {
        try {
            InputDevice dev = ev.getDevice();
            if (dev != null) {
                String name = dev.getName();
                if (name != null && name.toLowerCase().contains("pen")) return true;
            }
            return ev.getToolType(0) == MotionEvent.TOOL_TYPE_STYLUS;
        } catch (Throwable t) {
            return false;
        }
    }

    /**
     * 只有"鼠标型笔"需要我们自己合成左键。
     *
     * Winlator 的 TouchpadView.onTouchEvent 在 ACTION_DOWN 分支第一行就对 SOURCE_MOUSE
     * 直接 return true，所以像 WH851-545 那支 BLE 笔（SOURCE_MOUSE）永远不会按下左键，
     * 必须由我们补上。
     *
     * 而 Galaxy Tab 的 S Pen 是正规 STYLUS（Sources = TOUCHSCREEN|STYLUS，没有 MOUSE），
     * 原生触摸分支本来就会按下/抬起；我们再合成一次，就变成"一次点击 = 两次 click"，
     * 表现就是点一下被当成双击。
     */
    private static boolean needsSyntheticClick(MotionEvent ev) {
        try {
            // 只认 SOURCE_MOUSE 的 0x2000 位。
            // 不能写 (src & SOURCE_MOUSE) != 0：SOURCE_MOUSE=0x2002 里含 SOURCE_CLASS_POINTER(0x0002)，
            // 而 S Pen 的 0x5002 = STYLUS|TOUCHSCREEN|CLASS_POINTER 也带这一位，会误判成鼠标型笔
            // → 原生已经按过一次，我们再按一次 → 一次点击变成两声。
            return (ev.getSource() & 0x2000) != 0;
        } catch (Throwable t) {
            return false;
        }
    }

    private static int[] toContainer(View pad, MotionEvent ev) {
        resolveReflection();
        if (fXform == null || mTransformPoint == null) return null;
        try {
            float[] xform = (float[]) fXform.get(pad);
            if (xform == null) return null;
            // 和 Winlator 原生一样用 view 坐标：xform 是按 view 尺寸建的，
            // 用 getRawX() 在窗口不贴屏幕左上角（分屏、系统栏）时会整体偏移。
            float[] p = (float[]) mTransformPoint.invoke(null,
                    xform, ev.getX(), ev.getY());
            if (p == null || p.length < 2) return null;
            return new int[]{ (int) p[0], (int) p[1] };
        } catch (Throwable t) {
            return null;
        }
    }

    private static int[] toContainerAt(View pad, float vx, float vy) {
        resolveReflection();
        if (fXform == null || mTransformPoint == null) return null;
        try {
            float[] xform = (float[]) fXform.get(pad);
            if (xform == null) return null;
            float[] p = (float[]) mTransformPoint.invoke(null, xform, vx, vy);
            if (p == null || p.length < 2) return null;
            return new int[]{ (int) p[0], (int) p[1] };
        } catch (Throwable t) {
            return null;
        }
    }

    private static int[] toContainerScaledAt(View pad, float vx, float vy) {
        resolveReflection();
        if (fXform == null || mTransformPoint == null) return null;
        try {
            float[] xform = (float[]) fXform.get(pad);
            if (xform == null) return null;
            float[] p = (float[]) mTransformPoint.invoke(null, xform, vx, vy);
            if (p == null || p.length < 2) return null;
            return new int[]{
                    Math.round(p[0] * POS_SCALE),
                    Math.round(p[1] * POS_SCALE)
            };
        } catch (Throwable t) {
            return null;
        }
    }

    private static void syncLeftButton(View pad, int x, int y, float pressure, int action) {
        resolveReflection();
        if (fXServer == null || mInjectPointerMove == null
                || mInjectPress == null || mInjectRelease == null || BUTTON_LEFT == null) {
            return;
        }
        try {
            Object xs = fXServer.get(pad);
            if (xs == null) return;

            final long now = SystemClock.uptimeMillis();
            final long gap = now - lastPenEventMs;
            lastPenEventMs = now;

            // 笔离开感应区时 BLE 未必给 HOVER_EXIT，超时就自己松开，避免左键"粘住"
            if (penDown && gap > LOST_MS) {
                penDown = false;
                mInjectRelease.invoke(xs, BUTTON_LEFT);
                note("PEN_UP lost gap=" + gap);
            }

            // 抬笔判定要覆盖"HOVER_MOVE 且压力为 0"：很多笔抬起来先发悬停而不是 UP。
            // 只靠 pressure < PRESS_MIN 会在悬停仍有残余压力(如 0.002)时永不松手。
            final boolean hoverZero = (action == MotionEvent.ACTION_HOVER_MOVE
                    || action == MotionEvent.ACTION_HOVER_ENTER) && pressure <= 0f;
            final boolean lifted = action == MotionEvent.ACTION_UP
                    || action == MotionEvent.ACTION_CANCEL
                    || action == MotionEvent.ACTION_HOVER_EXIT
                    || action == MotionEvent.ACTION_POINTER_UP
                    || hoverZero;
            final boolean touching = action == MotionEvent.ACTION_DOWN
                    || action == MotionEvent.ACTION_MOVE
                    || action == MotionEvent.ACTION_POINTER_DOWN;

            if (!penDown) {
                // 触摸动作出现即代表笔尖接触（悬停走 HOVER_*，压力恒 0）；
                // 这支笔接触压力只有 0.03、移动时甚至 0.005，所以不能把压力当主判据。
                if (!lifted && (touching || pressure > PRESS_STRONG)) {
                    penDown = true;
                    // 先把光标移到笔尖再按下，顺序反了会点在旧位置
                    mInjectPointerMove.invoke(xs, x, y);
                    mInjectPress.invoke(xs, BUTTON_LEFT);
                    note("PEN_DOWN " + x + "," + y + " pr=" + pressure + " act=" + action);
                    flog("SYNTH DOWN pr=" + pressure + " act=" + action);
                    armReleaseWatchdog(pad);
                }
            } else if (lifted || (!touching && pressure <= 0f)) {
                penDown = false;
                mInjectRelease.invoke(xs, BUTTON_LEFT);
                note("PEN_UP pr=" + pressure + " act=" + action);
                flog("SYNTH UP pr=" + pressure + " act=" + action);
            } else {
                // 画线/拖动期间光标持续跟随笔尖
                mInjectPointerMove.invoke(xs, x, y);
            }
        } catch (Throwable t) {
            penDown = false;
            try { Log.w(TAG, "click failed: " + t); } catch (Throwable ignored) { }
        }
    }

    /**
     * 正规 STYLUS（Galaxy Tab 的 S Pen 这类，source = 0x5002 没有 0x2000 位）。
     *
     * 原生 TouchpadView 的行为：
     *   - 单指 MOVE 只 injectPointerMove（移动光标），**从不按左键** → 没有"拖动"
     *   - 抬起时 isTap()（时长<200ms 且 位移<10px）才 press+release 一次 → 点击
     *
     * 所以我们只做"拖动/长按"这半边，和 isTap() 严格互补，避免一次点击变两声：
     *   - 位移 ≥10px（屏幕坐标，与原生 travelDistance 同口径）或 按住 ≥200ms → 我们按下并保持
     *   - 抬手时如果是我们按下的，才松开
     *   - 快速轻点：我们什么都不做，交给原生点击
     */
    private static final float DRAG_PX = 10f;
    private static final long LONG_PRESS_MS = 200;

    private static float downSX, downSY;
    private static long downEventMs;
    private static boolean dragPressed;

    /**
     * 静默兜底：按钮按下之后，即使再也没有任何事件到来（笔离开屏幕、HOVER_EXIT 丢失），
     * 也要在 LOST_MS 之后把左键松开。
     * 原来的 gap 判断只在"下一个事件"里做，笔离开后就再没有下一个事件，
     * 于是左键一直粘着——表现就是"不抬笔"，光标划到哪画到哪。
     */
    private static void armReleaseWatchdog(final View pad) {
        if (pad == null) return;
        try {
            pad.postDelayed(new Runnable() {
                @Override public void run() {
                    try {
                        if (!penDown && !dragPressed && !fingerActive) return;
                        long gap = SystemClock.uptimeMillis() - lastPenEventMs;
                        if (gap < LOST_MS) {
                            pad.postDelayed(this, LOST_MS - gap + 50);
                            return;
                        }
                        releaseAll(pad, "watchdog gap=" + gap);
                    } catch (Throwable ignored) { }
                }
            }, LOST_MS + 50);
        } catch (Throwable ignored) { }
    }

    /** 把可能按下的左键统一松开（幂等）。 */
    private static void releaseAll(View pad, String why) {
        try {
            boolean did = false;
            if (penDown) { penDown = false; did = true; }
            if (dragPressed) { dragPressed = false; did = true; }
            if (fingerActive) { fingerActive = false; did = true; }
            if (did) {
                forceRelease(pad, why);
                note("PEN_UP " + why);
            }
        } catch (Throwable ignored) { }
    }

    /** 无条件松开左键（对没按下的情况也就是多发一次 release，无害）。 */
    private static void forceRelease(View pad, String why) {
        try {
            resolveReflection();
            if (fXServer == null || mInjectRelease == null || BUTTON_LEFT == null) return;
            Object xs = fXServer.get(pad);
            if (xs == null) return;
            mInjectRelease.invoke(xs, BUTTON_LEFT);
            // 自检：松手后立刻读一次指针的按键状态，确认真的松开了
            try {
                if (fPointer == null) {
                    fPointer = xs.getClass().getField("pointer");
                    Object ptr = fPointer.get(xs);
                    if (ptr != null) {
                        mIsPressed = ptr.getClass().getMethod("isButtonPressed",
                                Class.forName("com.winlator.xserver.Pointer$Button"));
                    }
                }
                Object ptr = fPointer != null ? fPointer.get(xs) : null;
                boolean down = ptr != null && mIsPressed != null
                        && Boolean.TRUE.equals(mIsPressed.invoke(ptr, BUTTON_LEFT));
                flog("RELEASE " + why + " stillPressed=" + down);
            } catch (Throwable ignored2) {
                flog("RELEASE " + why);
            }
        } catch (Throwable ignored) { }
    }

    private static void syncDragOnly(View pad, int x, int y, float pressure,
                                     MotionEvent ev, int action) {
        resolveReflection();
        if (fXServer == null || mInjectPointerMove == null
                || mInjectPress == null || mInjectRelease == null || BUTTON_LEFT == null) {
            return;
        }
        try {
            Object xs = fXServer.get(pad);
            if (xs == null) return;

            final long now = SystemClock.uptimeMillis();
            // 笔离开感应区却没有 UP：自己松开，避免左键粘死
            if (dragPressed && now - lastPenEventMs > LOST_MS) {
                dragPressed = false;
                mInjectRelease.invoke(xs, BUTTON_LEFT);
                flog("DRAG_UP lost");
            }
            lastPenEventMs = now;

            switch (action) {
                case MotionEvent.ACTION_DOWN:
                case MotionEvent.ACTION_POINTER_DOWN:
                    downSX = ev.getX();
                    downSY = ev.getY();
                    downEventMs = ev.getEventTime();
                    dragPressed = false;
                    /* 这里故意不按下：正规 STYLUS 的原生 isTap() 会在抬手时自己点一次
                     * （<200ms 且 <10px）。我们在 DOWN 就先按，等于一次轻点变成两次点击。
                     * 拖动/长按由下面的 moved / slow 判据接手，正好与 isTap() 互补。 */
                    break;

                case MotionEvent.ACTION_MOVE: {
                    if (!dragPressed) {
                        final float dx = ev.getX() - downSX;
                        final float dy = ev.getY() - downSY;
                        final boolean moved = (dx * dx + dy * dy) >= DRAG_PX * DRAG_PX;
                        final boolean slow = (ev.getEventTime() - downEventMs) >= LONG_PRESS_MS;
                        if (moved || slow) {
                            dragPressed = true;
                            mInjectPointerMove.invoke(xs, x, y);
                            mInjectPress.invoke(xs, BUTTON_LEFT);
                            note("DRAG_DOWN " + x + "," + y);
                            flog("DRAG_DOWN pr=" + pressure + " moved=" + moved + " slow=" + slow);
                            armReleaseWatchdog(pad);
                        }
                    } else {
                        mInjectPointerMove.invoke(xs, x, y);
                    }
                    break;
                }

                case MotionEvent.ACTION_UP:
                case MotionEvent.ACTION_CANCEL:
                case MotionEvent.ACTION_POINTER_UP:
                    if (dragPressed) {
                        dragPressed = false;
                        mInjectRelease.invoke(xs, BUTTON_LEFT);
                        note("DRAG_UP");
                        flog("DRAG_UP pr=" + pressure + " act=" + action);
                    }
                    break;

                case MotionEvent.ACTION_HOVER_MOVE:
                case MotionEvent.ACTION_HOVER_ENTER:
                    // 抬笔后先来悬停：压力归零就当我们自己按下过的那次松手
                    if (pressure <= 0f && dragPressed) {
                        dragPressed = false;
                        mInjectRelease.invoke(xs, BUTTON_LEFT);
                        note("DRAG_UP hover-zero");
                        flog("DRAG_UP pr=" + pressure + " (hover)");
                    }
                    break;

                default:
                    break;
            }
        } catch (Throwable t) {
            dragPressed = false;
        }
    }

    private static void resolveReflection() {
        if (reflectTried) return;
        reflectTried = true;
        try {
            Class<?> viewCls = Class.forName("com.winlator.widget.TouchpadView");
            try {
                fXServer = viewCls.getDeclaredField("xServer");
                fXServer.setAccessible(true);
            } catch (Throwable ignored) { }
            try {
                fXform = viewCls.getDeclaredField("xform");
                fXform.setAccessible(true);
            } catch (Throwable ignored) { }
            try {
                fNativeFingers = viewCls.getDeclaredField("fingers");
                fNativeFingers.setAccessible(true);
            } catch (Throwable ignored) { }
            try {
                fNativeNumFingers = viewCls.getDeclaredField("numFingers");
                fNativeNumFingers.setAccessible(true);
            } catch (Throwable ignored) { }
            try {
                fNativeScrolling = viewCls.getDeclaredField("scrolling");
                fNativeScrolling.setAccessible(true);
            } catch (Throwable ignored) { }

            Class<?> xformCls = Class.forName("com.winlator.math.XForm");
            mTransformPoint = xformCls.getMethod("transformPoint",
                    float[].class, float.class, float.class);

            Class<?> xsCls = Class.forName("com.winlator.xserver.XServer");
            mInjectPointerMove = xsCls.getMethod("injectPointerMove", int.class, int.class);

            Class<?> btnCls = Class.forName("com.winlator.xserver.Pointer$Button");
            BUTTON_LEFT = btnCls.getField("BUTTON_LEFT").get(null);
            mInjectPress = xsCls.getMethod("injectPointerButtonPress", btnCls);
            mInjectRelease = xsCls.getMethod("injectPointerButtonRelease", btnCls);

            Class<?> keyCls = Class.forName("com.winlator.xserver.XKeycode");
            KEY_PRIOR = keyCls.getField("KEY_PRIOR").get(null);
            KEY_NEXT = keyCls.getField("KEY_NEXT").get(null);
            mInjectKeyPress = xsCls.getMethod("injectKeyPress", keyCls);
            mInjectKeyRelease = xsCls.getMethod("injectKeyRelease", keyCls);

            KEY_CTRL_L = keyCls.getField("KEY_CTRL_L").get(null);
            KEY_SHIFT_L = keyCls.getField("KEY_SHIFT_L").get(null);
            KEY_SPACE = keyCls.getField("KEY_SPACE").get(null);
            KEY_Z = keyCls.getField("KEY_Z").get(null);
            KEY_Y = keyCls.getField("KEY_Y").get(null);
            KEY_0 = keyCls.getField("KEY_0").get(null);

            Log.d(TAG, "reflect ok xServer=" + (fXServer != null)
                    + " xform=" + (fXform != null)
                    + " move=" + (mInjectPointerMove != null));
        } catch (Throwable t) {
            try { Log.w(TAG, "reflect failed: " + t); } catch (Throwable ignored) { }
        }
    }

    // ------------------------------------------------------ 触控屏手势（0.3.7）

    private static Object xserver(View pad) {
        resolveReflection();
        if (fXServer == null) return null;
        try {
            return fXServer.get(pad);
        } catch (Throwable t) {
            return null;
        }
    }

    /** 反射把 XKeycode 常量按下/抬起。返回是否成功。 */
    private static boolean keyDown(Object xs, Object key) {
        if (xs == null || key == null || mInjectKeyPress == null) return false;
        try {
            mInjectKeyPress.invoke(xs, key);
            return true;
        } catch (Throwable t) {
            return false;
        }
    }

    private static void keyUp(Object xs, Object key) {
        if (xs == null || key == null || mInjectKeyRelease == null) return;
        try {
            mInjectKeyRelease.invoke(xs, key);
        } catch (Throwable ignored) {
        }
    }

    /**
     * 按顺序按下 keys，再逆序抬起。用于 Ctrl+Z / Ctrl+Y / Ctrl+0 / Ctrl+'+' / Ctrl+'-'。
     * keys 里可以同时有修饰键（Ctrl/Alt/Shift）和主键。
     */
    private static void keyTap(View pad, Object... keys) {
        Object xs = xserver(pad);
        if (xs == null || keys == null || keys.length == 0) return;
        for (Object k : keys) keyDown(xs, k);
        for (int i = keys.length - 1; i >= 0; i--) keyUp(xs, keys[i]);
    }

    /* SAI 默认快捷键：Ctrl+Z 撤销、Ctrl+Y 重做、Ctrl+0 全屏/适合窗口、
     * Ctrl+'+' 放大、Ctrl+'-' 缩小。'+' 在主键盘上是 Shift+'='，所以要带 Shift。 */
    private static void shortcutUndo(View pad) {
        keyTap(pad, KEY_CTRL_L, KEY_Z);
        flog("GEST undo ctrl+z");
        note("gesture -> Ctrl+Z (undo)");
        showToast(pad, "撤销 (Ctrl+Z)");
    }

    private static void shortcutRedo(View pad) {
        keyTap(pad, KEY_CTRL_L, KEY_Y);
        flog("GEST redo ctrl+y");
        note("gesture -> Ctrl+Y (redo)");
        showToast(pad, "重做 (Ctrl+Y)");
    }

    private static void shortcutFit(View pad) {
        keyTap(pad, KEY_CTRL_L, KEY_0);
        flog("GEST fit ctrl+0");
        note("gesture -> Ctrl+0 (fit)");
        showToast(pad, "适合窗口 / 居中全屏 (Ctrl+0)");
    }

    /**
     * 手势动作提示。只在撤销 / 重做 / 适合窗口三个一次性动作上弹，
     * 平移、缩放、旋转是连续操作，不弹。Toast 必须回主线程。
     */
    private static void showToast(final View pad, final String msg) {
        if (pad == null) return;
        try {
            pad.post(new Runnable() {
                @Override
                public void run() {
                    try {
                        android.content.Context ctx = pad.getContext();
                        if (ctx == null) return;
                        android.widget.Toast.makeText(ctx.getApplicationContext(), msg,
                                android.widget.Toast.LENGTH_SHORT).show();
                    } catch (Throwable ignored) {
                    }
                }
            });
        } catch (Throwable ignored) {
        }
    }

    /**
     * 两指缩放 -> PageUp / PageDown。
     *
     * 实测（SM-X810 + [PivInk]SAI 2026-10-19）：
     *   - PageUp / PageDown 是 SAI 默认的「以光标位置为中心放大/缩小」，稳定可用；
     *   - Ctrl+'-' 可以缩小，但 Ctrl+'+' / Ctrl+Shift+'=' 在这个构建里不放大；
     *   - Ctrl+KP_ADD 也不放大。
     * 所以统一用 PageUp/PageDown，和滚轮缩放（docs/12）走同一条已验证路径。
     */
    private static void shortcutZoom(View pad, boolean in) {
        keyTap(pad, in ? KEY_PRIOR : KEY_NEXT);
        flog("GEST zoom " + (in ? "in" : "out") + " (PageUp/PageDown)");
    }

    /**
     * 两指旋转 -> Shift+PageUp / Shift+PageDown。
     *
     * SAI 的旋转视图快捷键：Shift+PageUp = 逆时针、Shift+PageDown = 顺时针，
     * 每次约 11.3°（默认值）。比 Alt+Space+左键拖动可靠：在 Wine 里 Alt+Space
     * 很容易被系统菜单抢走，实测画布不转。
     */
    private static void rotateStep(View pad, boolean clockwise) {
        keyTap(pad, KEY_SHIFT_L, clockwise ? KEY_NEXT : KEY_PRIOR);
        flog("GEST rotate " + (clockwise ? "cw" : "ccw"));
    }

    private static Object buttonLeft() {
        resolveReflection();
        return BUTTON_LEFT;
    }

    private static void pointerDown(View pad) {
        Object xs = xserver(pad);
        Object left = buttonLeft();
        if (xs == null || left == null || mInjectPress == null) return;
        try {
            mInjectPress.invoke(xs, left);
        } catch (Throwable ignored) {
        }
    }

    private static void pointerUp(View pad) {
        Object xs = xserver(pad);
        Object left = buttonLeft();
        if (xs == null || left == null || mInjectRelease == null) return;
        try {
            mInjectRelease.invoke(xs, left);
        } catch (Throwable ignored) {
        }
    }

    /** 把视图坐标（fingertip 在 View 里的坐标）映射成容器坐标。 */
    private static int[] toContainerPoint(View pad, float vx, float vy) {
        resolveReflection();
        if (fXform == null || mTransformPoint == null) return null;
        try {
            float[] xform = (float[]) fXform.get(pad);
            if (xform == null) return null;
            float[] p = (float[]) mTransformPoint.invoke(null, xform, vx, vy);
            if (p == null || p.length < 2) return null;
            return new int[]{(int) p[0], (int) p[1]};
        } catch (Throwable t) {
            return null;
        }
    }

    /** 发送用坐标：容器坐标 * POS_SCALE，保留 1/8px 精度。 */
    private static int[] toContainerScaled(View pad, MotionEvent ev) {
        resolveReflection();
        if (fXform == null || mTransformPoint == null) return null;
        try {
            float[] xform = (float[]) fXform.get(pad);
            if (xform == null) return null;
            float[] p = (float[]) mTransformPoint.invoke(null, xform, ev.getX(), ev.getY());
            if (p == null || p.length < 2) return null;
            return new int[]{
                    Math.round(p[0] * POS_SCALE),
                    Math.round(p[1] * POS_SCALE)
            };
        } catch (Throwable t) {
            return null;
        }
    }

    /**
     * 虚拟鼠标按钮按下时，把 X 光标移到手指触点。
     *
     * InputControlsView 的按钮只注入 button press/release，不移动指针，所以
     * 光标停在别处时点击会落在旧位置。这里只对“绑定里含鼠标按键”的按钮生效，
     * Ctrl/Shift 这类键盘按钮不会让光标乱跳。
     *
     * smali: ControlElement.handleTouchDown 的 BUTTON 分支调用。
     */
    public static void moveCursorForVirtualButton(Object element, float x, float y) {
        if (element == null) return;
        try {
            if (fControlBindings == null) {
                fControlBindings = element.getClass().getDeclaredField("bindings");
                fControlBindings.setAccessible(true);
            }
            Object arr = fControlBindings.get(element);
            if (!(arr instanceof Object[])) return;

            boolean mouseButton = false;
            for (Object binding : (Object[]) arr) {
                if (binding == null) continue;
                if (mBindingGetPointerButton == null) {
                    mBindingGetPointerButton = binding.getClass().getMethod("getPointerButton");
                }
                if (mBindingGetPointerButton.invoke(binding) != null) {
                    mouseButton = true;
                    break;
                }
            }
            if (!mouseButton) return;

            if (fControlInputControlsView == null) {
                fControlInputControlsView = element.getClass().getDeclaredField("inputControlsView");
                fControlInputControlsView.setAccessible(true);
            }
            Object icv = fControlInputControlsView.get(element);
            if (icv == null) return;
            if (mInputControlsGetTouchpadView == null) {
                mInputControlsGetTouchpadView = icv.getClass().getMethod("getTouchpadView");
            }
            Object pad = mInputControlsGetTouchpadView.invoke(icv);
            if (!(pad instanceof View)) return;

            int[] p = toContainerPoint((View) pad, x, y);
            if (p != null) moveCursorTo((View) pad, p[0], p[1]);
        } catch (Throwable ignored) {
        }
    }

    /**
     * 清空 TouchpadView 原生的多指状态。
     *
     * 手势事件被 smali 提前 return 后，原生不会收到第二个手指的 POINTER_DOWN；
     * 但第一个手指已经在原生 fingers[] 里留下了记录。不清理的话，残留的单指状态
     * 会在手势结束后继续移动光标，甚至在抬手时补一次点击。这里用反射直接清空
     * fingers[] / numFingers / scrolling，等价于"原生从未见过这次触摸"。
     */
    private static void clearNativeFingers(View pad) {
        resolveReflection();
        try {
            if (fNativeFingers != null) {
                Object arr = fNativeFingers.get(pad);
                if (arr != null) {
                    for (int i = 0; i < 4; i++) java.lang.reflect.Array.set(arr, i, null);
                }
            }
            if (fNativeNumFingers != null) fNativeNumFingers.setByte(pad, (byte) 0);
            if (fNativeScrolling != null) fNativeScrolling.setBoolean(pad, false);
            flog("GEST native fingers cleared");
        } catch (Throwable ignored) {
        }
    }

    /**
     * 多指手势识别 + 快捷键/鼠标注入。
     *
     * 映射（全部基于两指/三指，单指不受影响）：
     *   两指轻点            -> Ctrl+Z（撤销）
     *   三指轻点            -> Ctrl+Y（重做）
     *   两指平移            -> Space + 左键拖动（平移画布）
     *   两指捏合/张开       -> PageUp / PageDown（以光标为中心缩放画布）
     *   两指旋转            -> Shift+PageUp / Shift+PageDown（每次约 11.3°）
     *   快速向内捏合        -> Ctrl+0（适合窗口/居中全屏）
     *
     * 事件被消费时返回 true，smali 侧直接 return，原生两指滚动/右键逻辑不再执行。
     */
    private static final class TouchGestures {
        private static final int IDLE = 0;
        private static final int CAND2 = 1;
        private static final int CAND3 = 2;
        private static final int PAN = 3;
        private static final int ROTATE = 4;
        private static final int ZOOM = 5;
        private static final int FIT = 6;
        private static final int IGNORE = 7;

        private static final float TAP_SLOP = 16f;
        private static final long TAP_MS = 380;
        private static final float FIT_RATIO = 0.62f;
        private static final long FIT_MS = 280;
        private static final float FIT_SLOP = 60f;
        /** 捏合收缩速度下限（比例/毫秒），防止普通快速缩小误触发"适合窗口"。 */
        private static final float FIT_SPEED = 0.0011f;
        private static final float ZOOM_STEP_PX = 55f;
        /** SAI 的 Shift+PageUp/PageDown 每次旋转约 11.3°，换算成弧度。 */
        private static final float ROTATE_STEP_RAD = 0.197f;

        private static int mode = IDLE;
        private static boolean active;
        private static long startMs;
        private static float cx0, cy0, dist0, angle0;
        private static float lastDist;
        /* 旋转：记上一次已经"消费"掉的角度，累计到 11.3° 就按一次旋转键。 */
        private static float rotLastAngle;
        private static float rotAccum;
        private static final float[] startX = new float[4];
        private static final float[] startY = new float[4];
        private static final boolean[] tracked = new boolean[4];
        private static float zoomAccum;
        private static int zoomSteps;
        private static long lastFitMs;
        private static boolean spaceHeld;
        private static boolean leftHeld;
        private static boolean logged;
        /* 一次手势识别完成后，剩余手指可能还会依次抬起。必须把这些事件
         * 全部消费掉，否则三指轻点抬起第一指触发重做后，剩下的两指
         * 会被当成一次新的「两指轻点」，紧接着又触发撤销。 */
        private static boolean consumeRest;

        static boolean onTouch(View pad, MotionEvent ev) {
            final int action = ev.getActionMasked();
            final int count = ev.getPointerCount();
            final long now = SystemClock.uptimeMillis();

            if (action == MotionEvent.ACTION_DOWN) {
                consumeRest = false;
                // 正常情况下手势在 UP 时已经结束；这里兜底一次，防止漏掉 UP 后
                // Space/Alt/左键一直按住。
                if (active) finish(pad);
                else reset();
                trackDown(ev, 0);
                return false;
            }

            if (consumeRest) {
                // 手势已经结束，但还有手指没抬完：全部消费到 ACTION_UP/CANCEL。
                if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                    consumeRest = false;
                }
                return true;
            }
            if (action == MotionEvent.ACTION_CANCEL) {
                if (active) {
                    finish(pad);
                    return true;
                }
                reset();
                return false;
            }

            if (action == MotionEvent.ACTION_POINTER_DOWN) {
                if (count < 2) return false;
                if (!active) {
                    start(pad, ev, count);
                    trackDown(ev, ev.getActionIndex());
                } else if (mode == CAND2 && count == 3) {
                    // 两指手势过程中又落下第三指：升级成三指轻点候选。
                    // 三指轻点通常就是 2 -> 3 落指，然后依次抬起。
                    mode = CAND3;
                    trackDown(ev, ev.getActionIndex());
                    computeStart(ev);
                } else {
                    // 已经在平移/缩放/旋转，或超过三指：结束当前操作并忽略后续。
                    if (mode == PAN || mode == ROTATE) endPointerGesture(pad);
                    mode = IGNORE;
                    trackDown(ev, ev.getActionIndex());
                }
                if (!logged) {
                    logged = true;
                    note("touch gestures enabled");
                }
                flog("GEST down n=" + count + " mode=" + mode);
                return true;
            }

            if (action == MotionEvent.ACTION_MOVE) {
                if (count < 2) return false;
                if (!active) start(pad, ev, count);
                update(pad, ev, now);
                return true;
            }

            if (action == MotionEvent.ACTION_POINTER_UP) {
                if (!active) return false;
                update(pad, ev, now);
                if (mode == CAND2 && count == 2) maybeTap(pad, ev, 2, now);
                else if (mode == CAND3 && count == 3) maybeTap(pad, ev, 3, now);
                finish(pad);
                return true;
            }

            if (action == MotionEvent.ACTION_UP) {
                if (!active) return false;
                finish(pad);
                return true;
            }
            return false;
        }

        private static void start(View pad, MotionEvent ev, int count) {
            active = true;
            startMs = SystemClock.uptimeMillis();
            mode = count == 2 ? CAND2 : (count == 3 ? CAND3 : IGNORE);
            java.util.Arrays.fill(tracked, false);
            for (int i = 0; i < ev.getPointerCount(); i++) {
                int id = ev.getPointerId(i);
                if (id >= 0 && id < 4) {
                    startX[id] = ev.getX(i);
                    startY[id] = ev.getY(i);
                    tracked[id] = true;
                }
            }
            computeStart(ev);
            // 原生可能已经按着左键/滚轮（单指拖动中途加入第二指），先松开。
            forceRelease(pad, "gesture start");
            clearNativeFingers(pad);
            flog("GEST start n=" + count);
        }

        private static void trackDown(MotionEvent ev, int index) {
            if (index < 0 || index >= ev.getPointerCount()) return;
            int id = ev.getPointerId(index);
            if (id >= 0 && id < 4) {
                startX[id] = ev.getX(index);
                startY[id] = ev.getY(index);
                tracked[id] = true;
            }
        }

        private static void computeStart(MotionEvent ev) {
            float[] g = geometry(ev);
            cx0 = g[0];
            cy0 = g[1];
            dist0 = g[2];
            angle0 = g[3];
            lastDist = dist0;
            zoomAccum = 0f;
        }

        /** 返回 {重心x, 重心y, 两指距离, 两指夹角}，坐标为 View 坐标。 */
        private static float[] geometry(MotionEvent ev) {
            final int n = Math.min(2, ev.getPointerCount());
            float cx = 0, cy = 0;
            for (int i = 0; i < n; i++) {
                cx += ev.getX(i);
                cy += ev.getY(i);
            }
            if (n > 0) {
                cx /= n;
                cy /= n;
            }
            float dist = 0f, angle = 0f;
            if (ev.getPointerCount() >= 2) {
                float dx = ev.getX(1) - ev.getX(0);
                float dy = ev.getY(1) - ev.getY(0);
                dist = (float) Math.hypot(dx, dy);
                angle = (float) Math.atan2(dy, dx);
            }
            return new float[]{cx, cy, dist, angle};
        }

        private static void update(View pad, MotionEvent ev, long now) {
            final int count = ev.getPointerCount();
            if (count > 3) {
                if (mode == PAN || mode == ROTATE) endPointerGesture(pad);
                mode = IGNORE;
                return;
            }
            if (count < 2) return;

            float[] g = geometry(ev);
            final float cx = g[0], cy = g[1], dist = g[2], angle = g[3];
            final float centroidMove = (float) Math.hypot(cx - cx0, cy - cy0);
            final long dt = now - startMs;
            final float ratio = dist / Math.max(dist0, 20f);

            // 快速向内捏合：适合窗口/居中全屏。
            // 误触太多，所以条件收紧：两指要缩到 62% 以下、在 280ms 内、
            // 重心基本不动、收缩速度够快；而且已经发过两次以上缩放键后
            // 不再判定（那时用户显然是在正常缩小）。
            final float shrinkSpeed = (1f - ratio) / Math.max(dt, 1L);
            if ((mode == CAND2 || mode == ZOOM)
                    && (mode != ZOOM || zoomSteps <= 1)
                    && dist0 >= 80f
                    && dt <= FIT_MS && ratio <= FIT_RATIO
                    && centroidMove <= FIT_SLOP && shrinkSpeed >= FIT_SPEED
                    && now - lastFitMs >= 600) {
                lastFitMs = now;
                shortcutFit(pad);
                mode = FIT;
                flog("GEST fit ratio=" + ratio + " dt=" + dt + " speed=" + shrinkSpeed);
                return;
            }

            if (mode == CAND2) {
                // 平移阈值从 18px 提高到 40px，并且要求平移分数明显大于
                // 旋转/缩放分数（1.2 倍以上）才判为平移。两指旋转时重心
                // 多多少少会动，这个改动避免「想旋转却被判成平移」。
                final float panScore = centroidMove / 40f;
                final float zoomScore = Math.abs(ratio - 1f) / 0.08f;
                final float rotScore = Math.abs(normalizeAngle(angle - angle0)) / 0.14f; // ~8°

                final boolean canPan = panScore >= 1.2f;   // 至少 48px 重心位移
                final boolean canZoom = zoomScore >= 1f;
                final boolean canRot = rotScore >= 1f;

                if (canRot && rotScore >= panScore * 0.8f && rotScore >= zoomScore * 0.8f) {
                    beginRotate(pad, angle);
                } else if (canZoom && zoomScore >= panScore * 0.8f) {
                    mode = ZOOM;
                    lastDist = dist;
                    zoomAccum = 0f;
                    zoomSteps = 0;
                    // SAI 的 PageUp/PageDown 以光标为中心缩放，先把光标放到两指重心。
                    moveTo(pad, cx, cy);
                    flog("GEST zoom begin dist=" + dist0);
                } else if (canPan) {
                    beginPan(pad, cx, cy);
                } else if (canRot) {
                    beginRotate(pad, angle);
                } else if (canZoom) {
                    mode = ZOOM;
                    lastDist = dist;
                    zoomAccum = 0f;
                    zoomSteps = 0;
                    moveTo(pad, cx, cy);
                    flog("GEST zoom begin dist=" + dist0);
                }
            }

            if (mode == CAND3) {
                // 三指只在"三根手指都基本没动"时才算轻点；一旦移动就忽略。
                if (centroidMove > TAP_SLOP || maxTravel(ev) > TAP_SLOP) mode = IGNORE;
                return;
            }

            if (mode == PAN) {
                moveTo(pad, cx, cy);
                return;
            }

            if (mode == ROTATE) {
                // 两指夹角变化 -> Shift+PageUp / Shift+PageDown。
                // 每次按键约 11.3°，累计到阈值就按一次，方向跟随手指旋转方向。
                final float delta = normalizeAngle(angle - rotLastAngle);
                rotLastAngle = angle;
                rotAccum += delta;
                while (rotAccum >= ROTATE_STEP_RAD) {
                    rotateStep(pad, true);
                    rotAccum -= ROTATE_STEP_RAD;
                }
                while (rotAccum <= -ROTATE_STEP_RAD) {
                    rotateStep(pad, false);
                    rotAccum += ROTATE_STEP_RAD;
                }
                return;
            }

            if (mode == ZOOM) {
                zoomAccum += (dist - lastDist);
                lastDist = dist;
                // 单个 MOVE 最多注入 3 次，避免两指猛地张开时一次刷出几十级缩放。
                int sent = 0;
                while (zoomAccum >= ZOOM_STEP_PX && sent < 3) {
                    shortcutZoom(pad, true);
                    zoomAccum -= ZOOM_STEP_PX;
                    zoomSteps++;
                    sent++;
                }
                while (zoomAccum <= -ZOOM_STEP_PX && sent < 3) {
                    shortcutZoom(pad, false);
                    zoomAccum += ZOOM_STEP_PX;
                    zoomSteps++;
                    sent++;
                }
            }
        }

        private static void beginPan(View pad, float cx, float cy) {
            Object xs = xserver(pad);
            if (xs == null) {
                mode = IGNORE;
                return;
            }
            mode = PAN;
            moveTo(pad, cx, cy);
            spaceHeld = keyDown(xs, KEY_SPACE);
            pointerDown(pad);
            leftHeld = true;
            flog("GEST pan begin");
        }

        private static void beginRotate(View pad, float angle) {
            mode = ROTATE;
            rotLastAngle = angle;
            rotAccum = 0f;
            flog("GEST rotate begin (Shift+PageUp/PageDown)");
        }

        private static void moveTo(View pad, float vx, float vy) {
            int[] p = toContainerPoint(pad, vx, vy);
            if (p != null) moveCursorTo(pad, p[0], p[1]);
        }

        private static void endPointerGesture(View pad) {
            if (leftHeld) {
                pointerUp(pad);
                leftHeld = false;
            }
            Object xs = xserver(pad);
            if (spaceHeld) {
                keyUp(xs, KEY_SPACE);
                spaceHeld = false;
            }
        }

        private static void finish(View pad) {
            endPointerGesture(pad);
            flog("GEST end mode=" + mode);
            reset();
            // 关键：一次轻点/手势只执行一次动作。剩余手指的 POINTER_UP/UP
            // 不再参与新的手势识别。
            consumeRest = true;
        }

        static void cancel(View pad) {
            if (active) finish(pad);
            else reset();
        }

        private static void reset() {
            mode = IDLE;
            active = false;
            startMs = 0;
            cx0 = cy0 = dist0 = angle0 = lastDist = 0f;
            rotLastAngle = 0f;
            rotAccum = 0f;
            zoomAccum = 0f;
            zoomSteps = 0;
            java.util.Arrays.fill(tracked, false);
        }

        private static void maybeTap(View pad, MotionEvent ev, int count, long now) {
            if (now - startMs > TAP_MS) {
                flog("GEST tap too slow dt=" + (now - startMs));
                return;
            }
            if (maxTravel(ev) > TAP_SLOP) {
                flog("GEST tap moved " + maxTravel(ev));
                return;
            }
            if (count == 2) {
                shortcutUndo(pad);
            } else if (count == 3) {
                shortcutRedo(pad);
            }
        }

        private static float maxTravel(MotionEvent ev) {
            float max = 0f;
            for (int i = 0; i < ev.getPointerCount(); i++) {
                int id = ev.getPointerId(i);
                if (id < 0 || id >= 4 || !tracked[id]) continue;
                float dx = ev.getX(i) - startX[id];
                float dy = ev.getY(i) - startY[id];
                max = Math.max(max, (float) Math.hypot(dx, dy));
            }
            return max;
        }

        private static float normalizeAngle(float a) {
            while (a > Math.PI) a -= 2 * Math.PI;
            while (a < -Math.PI) a += 2 * Math.PI;
            return a;
        }
    }

    // ---------------------------------------------------------------- UDP 发送

    private static void emit(int x, int y, float pressure, int action, boolean simulateHover) {
        emit(x, y, pressure, action, simulateHover, false);
    }

    private static void emit(int x, int y, float pressure, int action, boolean simulateHover,
                             boolean queueAll) {
        try {
            if (disabled) return;

            lastAction = action;
            lastPressure = pressure;

            final boolean lifting = (action == 1 || action == 3 || action == 6 || action == 10);
            final boolean pressing = (action == 0 || action == 5);

            if (lifting) {
                // 抬笔：先发 p=0 的抬笔样本；手指没有悬停流，再补两个"悬停"样本
                // （压力 0、位置各挪 1~2 px），否则 SAI 不收笔，下一笔会从这一笔的终点连过去。
                // 笔抬笔后会自己继续送 HOVER_MOVE，不需要替它补，所以只对手指补。
                //
                // 这是"两笔首尾相连"的真正原因（真机实测）：SAI 的 WinTab 笔画不会因为
                // 一个和最后一个点位置相同的零压包而结束。真实数位板抬笔后笔还在感应区里
                // 悬停，驱动会继续送**位置在变**的零压样本，SAI 收到这些样本才收笔。
                // 手指没有悬停事件，上一笔就一直敞着；下一笔的第一包从上一笔的终点连过去，
                // 看起来就是两笔被一条直线接上了。位置必须不同：实测同一位置补一个零压包
                // 不够，挪 1 px 就够。
                //
                // 同时把待发的移动样本丢掉：它可能比抬笔样本还早，却会排在 CRIT 之后发出，
                // 变成"抬笔之后又来一个 p>0"，等于重新落笔。
                synchronized (LOCK) {
                    hasPending = false;
                    lastQueuedX = -100000;
                    lastQueuedY = -100000;
                    if (simulateHover) {
                        if (CRIT.size() > 28) CRIT.clear();
                        // 靠右边缘时往外挪会被 send() 夹到同一个像素，往回挪
                        final int dx = (x + 2 * POS_SCALE < screenW * POS_SCALE) ? POS_SCALE : -POS_SCALE;
                        CRIT.add(new int[]{x, y, 0});
                        CRIT.add(new int[]{x + dx, y, 0});
                        CRIT.add(new int[]{x + 2 * dx, y, 0});
                    } else {
                        CRIT.add(new int[]{x, y, 0});
                    }
                    LOCK.notifyAll();
                    ensureWorker();
                }
                return;
            }

            int p;
            {
                float pr = pressure;
                if (pr < 0f) pr = 0f;
                if (pr > 1f) pr = 1f;
                p = Math.round(pr * PMAX);
                if (pressing && p < 1) p = 1;   // 明确按下时至少给 1
                if (p < 1) p = 0;               // 悬停：只移动不落笔
            }

            synchronized (LOCK) {
                if (pressing) {
                    // 落笔样本排队，不合并；队列有上限防止极端情况爆内存。
                    lastQueuedX = -100000;
                    lastQueuedY = -100000;
                    // 同时丢掉这里之前排队的样本：抬笔/悬停的 p=0 若排在新一笔的 DOWN 之后发出，
                    // 会把刚起笔的这一笔立刻收掉（轻画时最明显——几乎没有墨）。
                    hasPending = false;
                    if (CRIT.size() < 4096) CRIT.add(new int[]{x, y, p});
                    LOCK.notifyAll();
                    ensureWorker();
                    return;
                }
                if (queueAll) {
                    /* 笔的 history 样本默认逐个进队列，保持压力曲线；
                     * 长线/卡顿时队列会涨，这时按空间距离抽稀：只丢离
                     * 上一个入队点很近的样本，线的形状和拐点都还在。 */
                    hasPending = false;
                    int q = CRIT.size();
                    int minD = q > 1024 ? 6 * POS_SCALE
                             : q > 512  ? 4 * POS_SCALE
                             : q > 256  ? 2 * POS_SCALE : 0;
                    if (minD > 0 && lastQueuedX > -99999) {
                        long dx = (long) x - lastQueuedX;
                        long dy = (long) y - lastQueuedY;
                        if (dx * dx + dy * dy < (long) minD * minD) {
                            return;   // 太近，卡顿时丢掉
                        }
                    }
                    lastQueuedX = x;
                    lastQueuedY = y;
                    if (CRIT.size() >= 2048) CRIT.pollFirst();
                    CRIT.add(new int[]{x, y, p});
                    LOCK.notifyAll();
                    ensureWorker();
                    return;
                }
                pendingX = x;
                pendingY = y;
                pendingP = p;
                hasPending = true;
                LOCK.notifyAll();
            }

            ensureWorker();
        } catch (Throwable t) {
            disabled = true;
            try { Log.w(TAG, "disabled: " + t); } catch (Throwable ignored) { }
        }
    }

    private static void ensureWorker() {
        synchronized (LOCK) {
            if (starting || socket != null) return;
            starting = true;
        }
        Thread t = new Thread(new Runnable() {
            @Override
            public void run() {
                workerLoop();
            }
        }, "SaiPenSender");
        t.setDaemon(true);
        t.setPriority(Thread.MAX_PRIORITY);
        t.start();
    }

    private static void workerLoop() {
        try {
            loopback = InetAddress.getByName("127.0.0.1");
            DatagramSocket s = new DatagramSocket();
            synchronized (LOCK) {
                socket = s;
                LOCK.notifyAll();
            }
            Log.i(TAG, "pen bridge up, pmax=" + PMAX);
        } catch (Throwable t) {
            disabled = true;
            try { Log.w(TAG, "init failed: " + t); } catch (Throwable ignored) { }
            return;
        }

        while (!disabled) {
            int x, y, p;
            boolean critical = false;
            synchronized (LOCK) {
                if (CRIT.isEmpty() && !hasPending) {
                    try {
                        LOCK.wait(200);
                    } catch (InterruptedException e) {
                        return;
                    }
                }
                int[] c = CRIT.poll();
                if (c != null) {
                    x = c[0]; y = c[1]; p = c[2];
                    critical = true;
                } else if (hasPending) {
                    x = pendingX; y = pendingY; p = pendingP;
                    hasPending = false;
                } else {
                    continue;
                }
            }

            // 落笔/抬笔立刻发；普通移动才受限速约束
            long now = SystemClock.uptimeMillis();
            long wait = critical ? 0 : (MIN_SEND_MS - (now - lastSendMs));
            if (wait > 0) {
                try {
                    Thread.sleep(wait);
                } catch (InterruptedException ie) {
                    return;
                }
                synchronized (LOCK) {
                    // 睡眠期间的新移动样本覆盖之；critical 在队列里，下一轮立刻发
                    if (hasPending) {
                        x = pendingX; y = pendingY; p = pendingP;
                        hasPending = false;
                    }
                }
            }
            send(x, y, p);
            lastSendMs = SystemClock.uptimeMillis();
        }
    }

    private static void send(int x, int y, int p) {
        final int wireW = screenW * POS_SCALE;
        final int wireH = screenH * POS_SCALE;
        if (x < 0) x = 0; else if (x >= wireW) x = wireW - 1;
        if (y < 0) y = 0; else if (y >= wireH) y = wireH - 1;

        int wireY = wireH - y;        // 报文 y 从底部量

        String msg = seq + " " + p + " " + x + " " + wireY + " " + wireW + " " + wireH;
        byte[] data = msg.getBytes(StandardCharsets.US_ASCII);
        try {
            socket.send(new DatagramPacket(data, data.length, loopback, PORT));
            seq++;
            sentCount++;
            if (sentCount <= 32 || (sentCount & 31) == 0) {
                Log.d(TAG, "sent=" + sentCount + " p=" + p + " xy=" + x + "," + y
                        + " act=" + lastAction + " pr=" + lastPressure);
            }
        } catch (Throwable t) {
            disabled = true;
            try { Log.w(TAG, "send failed: " + t); } catch (Throwable ignored) { }
        }
    }
}
